import asyncio
import os

from nats.aio.client import Client as NATS

NATS_DEFAULT_CONNECT_TIMEOUT = 10
NATS_RECONNECT_TRIES = 2
SCOPE = "[NATS Communicator]"


class NatsCommunicator:
    def __init__(self, nats_server, logger=None, ue_service_id=None):
        self.nats_server = nats_server
        self.queue = None
        self.nc = None
        self.ue_service_id = ue_service_id
        self.logger = logger
        if self.ue_service_id:
            self.queue = asyncio.Queue()
            self.NATS_PUBLISH_CHANNEL_CMD_OUT_AGENT = os.environ.get(
                "NATS_PUBLISH_CHANNEL_CMD_OUT_AGENT",
                f"device.ueservice.{ue_service_id}.meas.iperf.ul",
            )
            self.NATS_PUBLISH_CHANNEL_CMD_OUT_SERVICE_CTRL = os.environ.get(
                "NATS_PUBLISH_CHANNEL_CMD_OUT_SERVICE_CTRL",
                f"device.ueservice.{ue_service_id}.meas.iperf.dl",
            )
            self.NATS_SUBSCRIBE_CHANNEL_CMD_AGENT = os.environ.get(
                "NATS_SUBSCRIBE_CHANNEL_CMD_AGENT",
                f"device.ueservice.{ue_service_id}.ue.command",
            )
            self.NATS_SUBSCRIBE_CHANNEL_CMD_SERVICE_CTRL = os.environ.get(
                "NATS_SUBSCRIBE_CHANNEL_CMD_SERVICE_CTRL",
                f"device.ueservice.{ue_service_id}.command",
            )
            self.NATS_SUBSCRIBE_CHANNEL_ENV_CONFIG = os.environ.get(
                "NATS_SUBSCRIBE_CHANNEL_ENV_CONFIG", "local.env_config"
            )
            self.NATS_PUBLISH_AGENTS_STATUS = os.environ.get(
                "NATS_PUBLISH_AGENTS_STATUS",
                f"device.ueservice.{ue_service_id}.ueagents.status",
            )

    async def create_client_and_connect(self):
        """ Create NATS client. """
        nc = NATS()
        self.logger.info(f"{SCOPE} Connecting to NATS {self.nats_server}...")
        await nc.connect(
            self.nats_server,
            connect_timeout=NATS_DEFAULT_CONNECT_TIMEOUT,
            max_reconnect_attempts=NATS_RECONNECT_TRIES,
        )
        if nc.is_connected:
            self.logger.info(f"{SCOPE} Connected to NATS {self.nats_server}")
        else:
            self.logger.error(f"{SCOPE} Failed to connect to NATS {self.nats_server}")
        self.nc = nc
        self.logger.info(f"{SCOPE} Initialized {self.nc}")
